-- P1/P2 Green Workflow: motor universal versionado. Workflows legados permanecem ativos.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `workflow_definicoes` (`codworkflow` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`codigo` VARCHAR(80) NOT NULL,`nome` VARCHAR(180) NOT NULL,`versao` INT UNSIGNED NOT NULL DEFAULT 1,`publicado` TINYINT(1) NOT NULL DEFAULT 0,`ativo` TINYINT(1) NOT NULL DEFAULT 1,`criado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`atualizado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`codworkflow`),UNIQUE KEY `UK_WORKFLOW_CODIGO_VERSAO` (`codigo`,`versao`),KEY `IX_WORKFLOW_PUBLICADO` (`codigo`,`publicado`,`ativo`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `workflow_etapas` (`codetapa` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`codworkflow` BIGINT UNSIGNED NOT NULL,`codigo` VARCHAR(80) NOT NULL,`nome` VARCHAR(180) NOT NULL,`ordem` INT NOT NULL DEFAULT 0,`prazo_dias` INT UNSIGNED NULL,`ativo` TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY (`codetapa`),UNIQUE KEY `UK_WORKFLOW_ETAPA` (`codworkflow`,`codigo`),CONSTRAINT `FK_WORKFLOW_ETAPA_DEF` FOREIGN KEY (`codworkflow`) REFERENCES `workflow_definicoes` (`codworkflow`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `workflow_transicoes` (`codtransicao` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`codworkflow` BIGINT UNSIGNED NOT NULL,`etapa_origem` VARCHAR(80) NOT NULL,`acao` VARCHAR(50) NOT NULL,`etapa_destino` VARCHAR(80) NOT NULL,`requer_motivo` TINYINT(1) NOT NULL DEFAULT 0,`ativo` TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY (`codtransicao`),UNIQUE KEY `UK_WORKFLOW_TRANSICAO` (`codworkflow`,`etapa_origem`,`acao`),CONSTRAINT `FK_WORKFLOW_TRANSICAO_DEF` FOREIGN KEY (`codworkflow`) REFERENCES `workflow_definicoes` (`codworkflow`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `workflow_instancias` (`codinstancia` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`codworkflow` BIGINT UNSIGNED NOT NULL,`chave_idempotencia` VARCHAR(191) NOT NULL,`origem_entidade` VARCHAR(100) NOT NULL,`origem_id` VARCHAR(100) NOT NULL,`etapa_atual` VARCHAR(80) NOT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'ATIVA',`codusuario_iniciador` BIGINT UNSIGNED NOT NULL,`codusuario_responsavel` BIGINT UNSIGNED NULL,`criado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`atualizado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,`finalizado_em` DATETIME NULL,PRIMARY KEY (`codinstancia`),UNIQUE KEY `UK_WORKFLOW_INST_IDEMP` (`chave_idempotencia`),KEY `IX_WORKFLOW_INST_RESP` (`codusuario_responsavel`,`status`),CONSTRAINT `FK_WORKFLOW_INST_DEF` FOREIGN KEY (`codworkflow`) REFERENCES `workflow_definicoes` (`codworkflow`),CONSTRAINT `FK_WORKFLOW_INST_USER` FOREIGN KEY (`codusuario_iniciador`) REFERENCES `usuarios` (`codusuario`),CONSTRAINT `FK_WORKFLOW_INST_RESP` FOREIGN KEY (`codusuario_responsavel`) REFERENCES `usuarios` (`codusuario`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS `workflow_historico` (`codhistorico` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`codinstancia` BIGINT UNSIGNED NOT NULL,`acao` VARCHAR(50) NOT NULL,`etapa_anterior` VARCHAR(80) NULL,`etapa_nova` VARCHAR(80) NOT NULL,`codusuario` BIGINT UNSIGNED NOT NULL,`motivo` VARCHAR(2000) NULL,`criado_em` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`codhistorico`),KEY `IX_WORKFLOW_HIST_INST` (`codinstancia`,`criado_em`),CONSTRAINT `FK_WORKFLOW_HIST_INST` FOREIGN KEY (`codinstancia`) REFERENCES `workflow_instancias` (`codinstancia`),CONSTRAINT `FK_WORKFLOW_HIST_USER` FOREIGN KEY (`codusuario`) REFERENCES `usuarios` (`codusuario`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `registros_migracao` (`codigo_migracao`,`origem`,`destino`,`tipo`,`versao`,`status`,`quantidade_registros`,`iniciada_em`,`concluida_em`,`detalhes`) VALUES ('GREEN_WORKFLOW_188','WorkflowService','workflow_definicoes/etapas/transicoes/instancias/historico','ESTRUTURA','4.0.1','CONCLUIDA',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,JSON_OBJECT('legado_preservado',TRUE,'versionado',TRUE,'idempotente',TRUE)) ON DUPLICATE KEY UPDATE `status`=VALUES(`status`),`concluida_em`=VALUES(`concluida_em`),`detalhes`=VALUES(`detalhes`);
